document.addEventListener("DOMContentLoaded",init);function wireQuickLinks(){document.querySelectorAll(".dashboard-quick-links .btn").forEach(btn=>{const href=btn.dataset.href;if(!href)return;btn.addEventListener("click",()=>{window.location.href=href})})}window.addEventListener("pageshow",()=>{document.querySelectorAll(".dashboard-quick-links .btn[disabled]").forEach(btn=>{btn.disabled=false})});async function init(){const owner=await Auth.guardOwnerAuth();if(!owner)return;document.getElementById("store-name-label").textContent=owner.storeName;document.getElementById("welcome-name").textContent=`, ${owner.storeName}`;document.getElementById("storefront-link").href=`../store.html?store=${encodeURIComponent(owner.storeSlug)}`;wireQuickLinks();renderStoreToggle(owner.status);document.getElementById("store-status-toggle").addEventListener("click",onToggleStoreStatus);if(owner.isAdmin){document.getElementById("admin-link-wrap").classList.remove("hidden")}const[productsRes,ordersRes,bookingsRes]=await Promise.all([Api.post("listOwnerProducts",{token:Auth.getToken()}),Api.post("listOwnerOrders",{token:Auth.getToken(),limit:100}),Api.post("listOwnerBookings",{token:Auth.getToken(),limit:100})]);if(productsRes.ok){const activeCount=productsRes.products.filter(p=>p.status==="active").length;document.getElementById("metric-products").textContent=activeCount}if(ordersRes.ok){document.getElementById("metric-orders").textContent=ordersRes.total!=null?ordersRes.total:ordersRes.orders.length;const pending=ordersRes.orders.filter(o=>o.status==="Pending Payment").length;document.getElementById("metric-pending").textContent=pending;setNavBadge("nav-orders-badge",pending)}if(bookingsRes.ok){const pendingBookings=bookingsRes.bookings.filter(b=>b.status==="Pending").length;setNavBadge("nav-bookings-badge",pendingBookings)}}function renderStoreToggle(status){const toggle=document.getElementById("store-status-toggle");if(!toggle)return;const open=status!=="standby"&&status!=="closed";toggle.setAttribute("aria-checked",open?"true":"false");toggle.classList.toggle("is-open",open);document.getElementById("store-status-open-label").classList.toggle("active",open);document.getElementById("store-status-closed-label").classList.toggle("active",!open);document.getElementById("store-status-toggle-hint").textContent=open?"Your store is OPEN — visible to customers.":"Your store is CLOSED — hidden from customers. You stay logged in."}async function onToggleStoreStatus(){const toggle=document.getElementById("store-status-toggle");const hint=document.getElementById("store-status-toggle-hint");const owner=Auth.getOwner();const next=owner.status==="standby"?"active":"standby";toggle.disabled=true;const res=await Api.post("setStoreStatus",{token:Auth.getToken(),status:next});toggle.disabled=false;if(!res.ok){hint.textContent=res.error||"Could not update store status. Please try again.";return}owner.status=next;Auth.saveSession(Auth.getToken(),owner);renderStoreToggle(next)}function setNavBadge(id,count){const badge=document.getElementById(id);if(!badge)return;if(count>0){badge.textContent=count>99?"99+":String(count);badge.classList.remove("hidden")}else{badge.classList.add("hidden")}}